use async_trait::async_trait; use chrono::{DateTime, Utc}; use nexus_core::{domain::errors::DomainError, ports::outbound::coude_insurance_repository::{CoudeInsurance, CoudeInsuranceRepository}}; use sqlx::PgPool; use super::pg_err;
pub struct PgCoudeInsuranceRepository { pool: PgPool }
impl PgCoudeInsuranceRepository { pub fn new(pool: PgPool) -> Self { Self { pool } } }
#[async_trait] impl CoudeInsuranceRepository for PgCoudeInsuranceRepository {
 async fn buy(&self, guild_id: &str, user_id: &str, is_scam: bool) -> Result<CoudeInsurance, DomainError> { let mut tx=self.pool.begin().await.map_err(pg_err)?; let (balance_after,):(i64,)=sqlx::query_as("UPDATE nexus_wallets SET coins=coins-50,total_spent=total_spent+50,updated_at=NOW() WHERE guild_id=$1 AND user_id=$2 AND coins>=50 RETURNING coins").bind(guild_id).bind(user_id).fetch_optional(&mut *tx).await.map_err(pg_err)?.ok_or_else(||DomainError::Validation("solde insuffisant (50 coins)".into()))?; sqlx::query("UPDATE nexus_coude_insurances SET active=FALSE WHERE guild_id=$1 AND user_id=$2 AND active=TRUE").bind(guild_id).bind(user_id).execute(&mut *tx).await.map_err(pg_err)?; let (expires_at,):(DateTime<Utc>,)=sqlx::query_as("INSERT INTO nexus_coude_insurances (guild_id,user_id,is_scam,expires_at) VALUES ($1,$2,$3,NOW()+INTERVAL '1 hour') RETURNING expires_at").bind(guild_id).bind(user_id).bind(is_scam).fetch_one(&mut *tx).await.map_err(pg_err)?; sqlx::query("INSERT INTO nexus_wallet_transactions (guild_id,user_id,amount,balance_after,source,description) VALUES ($1,$2,-50,$3,'coude_insurance','Assurance Coup de Coude')").bind(guild_id).bind(user_id).bind(balance_after).execute(&mut *tx).await.map_err(pg_err)?; tx.commit().await.map_err(pg_err)?; Ok(CoudeInsurance{is_scam,expires_at}) }
 async fn active(&self,guild_id:&str,user_id:&str)->Result<Option<CoudeInsurance>,DomainError>{ let row:Option<(bool,DateTime<Utc>)>=sqlx::query_as("SELECT is_scam,expires_at FROM nexus_coude_insurances WHERE guild_id=$1 AND user_id=$2 AND active=TRUE AND expires_at>NOW() ORDER BY expires_at DESC LIMIT 1").bind(guild_id).bind(user_id).fetch_optional(&self.pool).await.map_err(pg_err)?; Ok(row.map(|(is_scam,expires_at)|CoudeInsurance{is_scam,expires_at})) }
}
